const int SENSOR_PIN = {{OUT}};
const float BETA = 3950;  // thermistor beta coefficient

#if defined(ESP32)
const float ADC_MAX = 4095.0;  // 12-bit ADC
const float ADC_VREF = 3.3;
#else
const float ADC_MAX = 1023.0;  // 10-bit ADC
const float ADC_VREF = 5.0;
#endif

void setup() {
  Serial.begin(115200);
}

void loop() {
  int raw = analogRead(SENSOR_PIN);
  float celsius = 1 / (log(1 / (ADC_MAX / raw - 1)) / BETA + 1.0 / 298.15) - 273.15;
  Serial.print("Temperature: ");
  Serial.print(celsius);
  Serial.println(" C");
  delay(1000);
}
